{
  "name": "RGB三色发光二极管",
  "name_en": "RGB LED",
  "manufacturer": "",
  "description": "一种通过 GPIO 控制红、绿、蓝三个通道的全彩发光二极管，可设置颜色、通道强度以及闪烁和渐亮渐暗效果，常用于状态指示、视觉提示和教学实验。",
  "description_en": "A full-color LED component controlled through GPIO with separate red, green, and blue channels. It supports color setting, channel intensity control, blinking, and pulsing, and is commonly used for status indication, visual feedback, and teaching experiments.",
  "tag_hints": [
    "RGB illumination",
    "GPIO output",
    "PWM brightness control",
    "color mixing",
    "status indicator",
    "visual feedback"
  ],
  "actions": [
    {
      "action_name": "auto-blink",
      "description": "使 RGB LED 按设定的开关时间与颜色重复闪烁。",
      "description_en": "Make the RGB LED blink repeatedly with configurable timing and colors."
    },
    {
      "action_name": "auto-blue",
      "description": "获取/设置/定义蓝色通道强度。",
      "description_en": "get/set/define blue channel intensity"
    },
    {
      "action_name": "auto-close",
      "description": "关闭设备并释放 GPIO 资源。",
      "description_en": "Close the device and release GPIO resources."
    },
    {
      "action_name": "auto-color",
      "description": "获取/设置/定义 LED 颜色。",
      "description_en": "get/set/define LED color"
    },
    {
      "action_name": "auto-green",
      "description": "获取/设置/定义绿色通道强度。",
      "description_en": "get/set/define green channel intensity"
    },
    {
      "action_name": "auto-off",
      "description": "关闭 LED。",
      "description_en": "Turn the LED off."
    },
    {
      "action_name": "auto-on",
      "description": "打开 LED 并设为白色全亮。",
      "description_en": "Turn the LED on to full white."
    },
    {
      "action_name": "auto-pulse",
      "description": "使 RGB LED 按设定颜色重复渐亮渐暗。",
      "description_en": "Make the RGB LED repeatedly fade in and out with configurable colors."
    },
    {
      "action_name": "auto-red",
      "description": "获取/设置/定义红色通道强度。",
      "description_en": "get/set/define red channel intensity"
    },
    {
      "action_name": "auto-toggle",
      "description": "切换 LED 的开关状态。",
      "description_en": "Toggle the LED state."
    },
    {
      "action_name": "auto-value",
      "description": "获取/设置/定义 RGB 三元组输出值。",
      "description_en": "get/set/define RGB tuple output value"
    },
    {
      "action_name": "auto-closed",
      "description": "获取/设置/定义设备是否已关闭。",
      "description_en": "get/set/define whether the device is closed"
    },
    {
      "action_name": "auto-is_active",
      "description": "获取/设置/定义 LED 是否处于激活状态。",
      "description_en": "get/set/define whether the LED is active"
    },
    {
      "action_name": "auto-active_high",
      "description": "获取/设置/定义高电平有效输出逻辑。",
      "description_en": "get/set/define active-high output logic"
    },
    {
      "action_name": "auto-frequency",
      "description": "获取/设置/定义 PWM 输出频率。",
      "description_en": "get/set/define PWM output frequency"
    },
    {
